import re
from pathlib import Path
from shlex import quote
from typing import Any, Iterable, Optional, Set

from ci.praktika.git import Git
from ci.praktika.info import Info
from ci.praktika.utils import Shell

FILE_WITH_VERSION_PATH = "./cmake/autogenerated_versions.txt"
_TAG_PATTERN = re.compile(
    r"\Av\d{2}([.][1-9]\d*){3}-(new|testing|prestable|stable|lts)\Z"
)

# Canonical layout of cmake/autogenerated_versions.txt as committed to the repo.
VERSIONS_TEMPLATE = """\
# This variables autochanged by ci/jobs/scripts/create_release.py:

# NOTE: VERSION_REVISION has nothing common with DBMS_TCP_PROTOCOL_VERSION,
# only DBMS_TCP_PROTOCOL_VERSION should be incremented on protocol changes.
SET(VERSION_REVISION {revision})
SET(VERSION_MAJOR {major})
SET(VERSION_MINOR {minor})
SET(VERSION_PATCH {patch})
SET(VERSION_GITHASH {githash})
SET(VERSION_DESCRIBE {describe})
SET(VERSION_STRING {string})
# end of autochange
"""


class VersionType:
    # `new` is the type stamped on master right after a release branch is cut
    # (the `vX.Y.1.1-new` marker); the CreateRelease flow relies on it.
    NEW = "new"
    TESTING = "testing"
    STABLE = "stable"
    LTS = "lts"
    CLOUD = "cloud"
    VALID = {NEW, TESTING, STABLE, LTS, CLOUD}


def _read_versions(text: Optional[str] = None) -> dict:
    """Parse `cmake/autogenerated_versions.txt`: the checked-out file, or `text`
    (the file's content at another commit) when given."""
    if text is None:
        text = Path(FILE_WITH_VERSION_PATH).read_text(encoding="utf-8")
    versions = {}
    for line in text.splitlines():
        line = line.strip()
        if not line.startswith("SET("):
            continue
        name, value = line[4:-1].split(maxsplit=1)
        name = name.removeprefix("VERSION_").lower()
        try:
            value = int(value)
        except ValueError:
            pass
        versions[name] = value
    return versions


def _write_version_file(version_dict: dict) -> None:
    Path(FILE_WITH_VERSION_PATH).write_text(
        VERSIONS_TEMPLATE.format_map(version_dict), encoding="utf-8"
    )


def _tweak_from_git(githash, target: str = "HEAD") -> int:
    """The tweak: the commit count since `githash` on the first-parent history
    up to `target` (`git rev-list --count`). It does not use tags, so tags need
    not be fetched.

    Raises on a shallow checkout or any git error instead of silently returning a
    default -- a caller that can tolerate an unknown tweak must opt into that
    explicitly (see `CHVersion.get_current_version`)."""
    return int(
        Shell.get_output(
            f"git rev-list --count --first-parent {githash}..{target}",
            verbose=True,
        )
    )


def _version_type_from_describe(versions: dict) -> str:
    """Recover the version type from the file's `VERSION_DESCRIBE` suffix, which
    is `v<string>-<version_type>`."""
    describe = str(versions.get("describe", ""))
    return describe.rsplit("-", 1)[1] if "-" in describe else ""


class CHVersion:
    """The ClickHouse release version.

    A stateful model (`major.minor.patch.tweak`, plus `revision`, `githash` and
    `version_type`, with the derived `string`/`describe` kept in sync) that the
    release process reads, bumps and writes. `get_current_version` /
    `get_release_version` read it from `cmake/autogenerated_versions.txt` without
    consulting the CI `Info` context, so they are safe inside a checkout of an
    arbitrary release commit; `get_current_version_from_ci_pipeline` reads it back
    from the pipeline kv storage for jobs that run without a full checkout.
    """

    def __init__(
        self,
        major,
        minor,
        patch,
        revision,
        tweak=1,
        githash="",
        version_type="",
    ):
        self.major = int(major)
        self.minor = int(minor)
        self.patch = int(patch)
        self.revision = int(revision)
        self.tweak = int(tweak)
        self.githash = githash
        self.version_type = version_type
        self._refresh()

    def _refresh(self) -> "CHVersion":
        """Recompute the derived `string`/`describe` members from the parts."""
        self.string = f"{self.major}.{self.minor}.{self.patch}.{self.tweak}"
        self.describe = (
            f"v{self.string}-{self.version_type}" if self.version_type else ""
        )
        return self

    # --- reading / writing the version model ---------------------------------

    @classmethod
    def get_current_version(
        cls, with_tweak: bool = True, no_strict: bool = False
    ) -> "CHVersion":
        """The version currently in `cmake/autogenerated_versions.txt`.

        `version_type` is read from the file's `VERSION_DESCRIBE` suffix and the
        githash is the current `HEAD`. With `with_tweak`, the tweak is the commit
        count since the file's githash (git history, no tags); on a shallow
        checkout that count cannot be computed, so this raises unless `no_strict`
        is set, in which case the tweak stays 1. Consults neither the CI `Info`
        context nor `_Environment`, so it is safe inside a checkout of an
        arbitrary release commit."""
        versions = _read_versions()
        tweak = 1
        if with_tweak:
            try:
                tweak = _tweak_from_git(versions["githash"])
            except Exception:
                if not no_strict:
                    raise
        return cls(
            versions["major"],
            versions["minor"],
            versions["patch"],
            versions["revision"],
            tweak=tweak,
            githash=Shell.get_output("git rev-parse HEAD") or "0" * 40,
            version_type=_version_type_from_describe(versions),
        )

    @classmethod
    def get_version_at_commit(cls, commit: str) -> "CHVersion":
        """The version `get_current_version` would have computed with `commit`
        checked out, without checking it out: the version file is read as of
        `commit` (`git show`), and the tweak is counted from that file's githash
        up to `commit`. Each commit must use its own file, not `HEAD`'s: a
        version bump moves both the version parts and the githash baseline.
        Used to backfill `version_history` rows for commits a batched `push`
        skipped -- see `ci/jobs/scripts/workflow_hooks/version_log.py`. Raises
        on any git error."""
        versions = _read_versions(
            Shell.get_output(
                f"git show {commit}:{FILE_WITH_VERSION_PATH.removeprefix('./')}",
                strict=True,
            )
        )
        return cls(
            versions["major"],
            versions["minor"],
            versions["patch"],
            versions["revision"],
            tweak=_tweak_from_git(versions["githash"], commit),
            githash=commit,
            version_type=_version_type_from_describe(versions),
        )

    @classmethod
    def get_release_version(cls) -> "CHVersion":
        """The release version exactly as stored in the file -- githash and tweak
        as committed, without recomputing anything from git. For the CreateRelease
        workflow."""
        versions = _read_versions()
        string = str(versions.get("string", ""))
        tweak = int(string.rsplit(".", 1)[1]) if string.count(".") >= 3 else 1
        return cls(
            versions["major"],
            versions["minor"],
            versions["patch"],
            versions["revision"],
            tweak=tweak,
            githash=str(versions.get("githash", "")),
            version_type=_version_type_from_describe(versions),
        )

    @classmethod
    def get_current_version_from_ci_pipeline(cls):
        """The version stored in the CI pipeline kv data during the build (see
        `store_version_data_in_ci_pipeline`), for jobs that run without a full
        checkout. Returns None when nothing was stored yet."""
        data = Info().get_kv_data("version")
        return cls.from_dict(data) if data else None

    @classmethod
    def from_dict(cls, data: dict) -> "CHVersion":
        string = str(data.get("string", ""))
        tweak = data.get("tweak")
        if tweak is None:
            tweak = int(string.rsplit(".", 1)[1]) if string.count(".") >= 3 else 1
        return cls(
            data["major"],
            data["minor"],
            data["patch"],
            data["revision"],
            tweak=tweak,
            githash=str(data.get("githash", "")),
            version_type=_version_type_from_describe(data),
        )

    def to_dict(self) -> dict:
        version_dict = {
            "revision": self.revision,
            "major": self.major,
            "minor": self.minor,
            "patch": self.patch,
            "tweak": self.tweak,
            "githash": self.githash,
            "describe": self.describe,
            "string": self.string,
        }
        missing = [k for k in ("githash", "describe", "string") if not version_dict[k]]
        assert not missing, f"version fields not set: {missing} in {version_dict}"
        return version_dict

    def write(self) -> None:
        """Write this version to `cmake/autogenerated_versions.txt`."""
        _write_version_file(self.to_dict())

    # --- bumping -------------------------------------------------------------

    def bump_release(self) -> "CHVersion":
        """Bump the minor version (or wrap to the next major when minor reaches 12)."""
        if self.minor < 12:
            self.minor += 1
        else:
            self.major += 1
            self.minor = 1
        self.revision += 1
        self.patch = 1
        self.tweak = 1
        return self._refresh()

    def bump_patch(self) -> "CHVersion":
        self.revision += 1
        self.patch += 1
        self.tweak = 1
        return self._refresh()

    # --- comparison / rendering ----------------------------------------------

    def with_description(self, version_type: str) -> "CHVersion":
        if version_type not in VersionType.VALID:
            raise ValueError(f"version type {version_type!r} not in {VersionType.VALID}")
        self.version_type = version_type
        return self._refresh()

    def with_tweak(self, tweak: int) -> "CHVersion":
        self.tweak = int(tweak)
        return self._refresh()

    @property
    def is_lts(self) -> bool:
        return self.minor % 5 == 3

    def get_stable_release_type(self) -> str:
        return VersionType.LTS if self.is_lts else VersionType.STABLE

    def is_older(self, other: "CHVersion") -> bool:
        """Whether this is an older release than `other`, by release triple
        (major, minor, patch). The tweak is a within-patch commit count and does
        not define a newer release."""
        return (self.major, self.minor, self.patch) < (
            other.major,
            other.minor,
            other.patch,
        )

    # --- CI pipeline kv storage ----------------------------------------------

    def store_version_data_in_ci_pipeline(self) -> None:
        version = self.to_dict()
        print(f"Store version in pipeline kv data: [version={version}]")
        Info().store_kv_data("version", version)


class ClickHouseVersion(CHVersion):
    """Ordered public release version used by Docker and upgrade tooling.

    Public tags allow `prestable`, but not the release workflow's `cloud` type.
    Ordering includes the tweak; `CHVersion.is_older` compares release triples.
    """

    @property
    def description(self) -> str:
        return self.version_type

    @property
    def is_supported(self) -> bool:
        return self.description in (VersionType.STABLE, VersionType.LTS)

    def with_description(self, version_type: str) -> "ClickHouseVersion":
        valid = ("new", "testing", "prestable", "stable", "lts")
        if version_type not in valid:
            raise ValueError(f"version type {version_type} not in {valid}")
        self.version_type = version_type
        return self._refresh()

    def __eq__(self, other: Any) -> bool:
        if not isinstance(self, type(other)):
            return NotImplemented
        return bool(
            self.major == other.major
            and self.minor == other.minor
            and self.patch == other.patch
            and self.tweak == other.tweak
        )

    def __lt__(self, other: Any) -> bool:
        if not isinstance(self, type(other)):
            return NotImplemented
        for part in ("major", "minor", "patch", "tweak"):
            if getattr(self, part) < getattr(other, part):
                return True
            if getattr(self, part) > getattr(other, part):
                return False

        return False

    def __le__(self, other: "ClickHouseVersion") -> bool:
        return self == other or self < other

    def __hash__(self):
        return hash(self.__repr__)

    def __str__(self):
        return f"{self.string}"

    def __repr__(self):
        return (
            f"<ClickHouseVersion({self.major},{self.minor},{self.patch},{self.tweak},"
            f"'{self.description}')>"
        )


def get_abs_path(path: Path | str) -> Path:
    root = Shell.get_output(
        f"git -C {quote(str(Path(__file__).resolve().parents[3]))} rev-parse --show-toplevel",
        strict=True,
    )
    return (Path(root) / path).absolute()


def get_version_from_repo(
    versions_path: Path | str = FILE_WITH_VERSION_PATH,
) -> ClickHouseVersion:
    versions = _read_versions(get_abs_path(versions_path).read_text(encoding="utf-8"))
    return ClickHouseVersion(
        versions["major"],
        versions["minor"],
        versions["patch"],
        versions["revision"],
        githash="0" * 40,
    )


def get_version_from_string(version: str) -> ClickHouseVersion:
    parts = version.split(".")
    if len(parts) != 4:
        raise ValueError(f"{version} does not contain 4 parts")
    return ClickHouseVersion(*parts[:3], revision=-1, tweak=parts[3], githash="0" * 40)


def get_version_from_tag(tag: str) -> ClickHouseVersion:
    if tag and not _TAG_PATTERN.match(tag):
        raise ValueError(f"last tag {tag} doesn't match the pattern")
    tag, description = tag[1:].split("-", 1)
    return get_version_from_string(tag).with_description(description)


def get_tagged_versions() -> list[ClickHouseVersion]:
    versions = []
    for tag in Git.get_tags(cwd=get_abs_path(".")):
        try:
            versions.append(get_version_from_tag(tag))
        except ValueError:
            continue
    return sorted(versions)


def get_supported_versions(
    versions: Optional[Iterable[ClickHouseVersion]] = None,
) -> Set[ClickHouseVersion]:
    supported_stable = set()  # type: Set[ClickHouseVersion]
    supported_lts = set()  # type: Set[ClickHouseVersion]
    if versions:
        versions = list(versions)
    else:
        # checks that repo is not shallow in background
        versions = [v for v in get_tagged_versions() if v.is_supported]
    versions.sort()
    versions.reverse()
    for version in versions:
        if len(supported_stable) < 3:
            if not {
                sv
                for sv in supported_stable
                if version.major == sv.major and version.minor == sv.minor
            }:
                supported_stable.add(version)
        if (version.description == VersionType.LTS or version.is_lts) and len(
            supported_lts
        ) < 2:
            if not {
                sv
                for sv in supported_lts
                if version.major == sv.major and version.minor == sv.minor
            }:
                supported_lts.add(version)
        if len(supported_stable) == 3 and len(supported_lts) == 2:
            break
    return supported_lts.union(supported_stable)


